let ano=document.getElementById("ano"),linksMenu=(ano&&(ano.textContent=(new Date).getFullYear()),document.querySelectorAll(".menu a"));linksMenu.forEach(function(e){e.addEventListener("click",function(){linksMenu.forEach(function(e){e.classList.remove("ativo"),e.removeAttribute("aria-current")}),e.classList.add("ativo"),e.setAttribute("aria-current","page")})}),document.querySelectorAll(".product-button").forEach(function(t){t.addEventListener("click",function(e){e.preventDefault();e=t.closest(".product-item").querySelector("h4").textContent;t.textContent="Selecionado: "+e,t.classList.add("selecionado")})});